  formatDate(date) {
    if (!date)
      return "\u0411\u0435\u0437\u043B\u0438\u043C\u0438\u0442";
    const day = date.getDate().toString().padStart(2, "0");
    const month = (date.getMonth() + 1).toString().padStart(2, "0");
    const year = date.getFullYear();
    return `${day}.${month}.${year}`;
  }
  formatTime(date) {
    if (!date)
      return "";
    const hours = date.getHours().toString().padStart(2, "0");
    const minutes = date.getMinutes().toString().padStart(2, "0");
    return `${hours}:${minutes}`;
  }
  formatDateTime(date) {
    if (!date)
      return "\u041D\u0435 \u0443\u043A\u0430\u0437\u0430\u043D\u043E";
    const day = date.getDate().toString().padStart(2, "0");
    const month = (date.getMonth() + 1).toString().padStart(2, "0");
    const year = date.getFullYear();
    const hours = date.getHours().toString().padStart(2, "0");
    const minutes = date.getMinutes().toString().padStart(2, "0");
    return `${day}.${month}.${year} ${hours}:${minutes}`;
  }
  parseDate(dateStr) {
    const dateRegex = /^(\d{2})\.(\d{2})\.(\d{4})$/;
    const match = dateStr.match(dateRegex);
    if (!match)
      return null;
    const day = parseInt(match[1]);
    const month = parseInt(match[2]) - 1;
    const year = parseInt(match[3]);
    if (day < 1 || day > 31 || month < 0 || month > 11 || year < 1900 || year > 2100) {
      return null;
    }
    const date = new Date(year, month, day);
    if (date.getDate() !== day || date.getMonth() !== month || date.getFullYear() !== year) {
      return null;
    }
    return date;
  }
  getDaysRemainingText(days) {
    if (days === -1)
      return "\u0411\u0435\u0437\u043B\u0438\u043C\u0438\u0442";
    if (days <= 0)
      return "\u0418\u0441\u0442\u0451\u043A";
    if (days === 1)
      return "1 \u0434\u0435\u043D\u044C";
    if (days < 5)
      return `${days} \u0434\u043D\u044F`;
    return `${days} \u0434\u043D\u0435\u0439`;
  }
  // Подсчет использованных запросов за сегодня
  calculateDailyUsage(user, modelsList) {
    if (!user || !user.models) {
      return 0;
    }
    const todayDate = getMoscowDate();
    let totalUsage = 0;
    for (const [modelName, modelData] of Object.entries(user.models)) {
      if (modelsList.includes(modelName) && modelData.dates && modelData.dates[todayDate]) {
        totalUsage += modelData.dates[todayDate];
      }
    }
    return totalUsage;
  }
