// src/agent-tools/tools/search.ts
var import_obsidian42 = require("obsidian");
var EXCLUDED_PATHS = ["zFlowWriter-ai"];
function isExcludedPath(path2) {
  const normalizedPath = path2.replace(/\\/g, "/");
  return EXCLUDED_PATHS.some(
    (excluded) => normalizedPath === excluded || normalizedPath.startsWith(excluded + "/") || normalizedPath.startsWith("/" + excluded + "/") || normalizedPath.startsWith("/" + excluded)
  );
}
function isWithinWorkingDirectory(path2, workingDirectory) {
  if (workingDirectory === "/" || workingDirectory === "") {
    return true;
  }
  const normalizedPath = path2.replace(/\\/g, "/").replace(/^\/+/, "").replace(/\/+$/, "");
  const normalizedWorkDir = workingDirectory.replace(/^\/+/, "").replace(/\/+$/, "");
  return normalizedPath === normalizedWorkDir || normalizedPath.startsWith(normalizedWorkDir + "/");
}
function isExcludedByUser(path2, excludeFolders) {
  if (!(excludeFolders == null ? void 0 : excludeFolders.length))
    return false;
  const pathParts = path2.replace(/\\/g, "/").split("/").filter((p) => p);
  return excludeFolders.some((folder) => {
    const normalizedFolder = folder.replace(/^\/+/, "").replace(/\/+$/, "");
    return pathParts[0] === normalizedFolder;
  });
}
function findNearestHeading(content, matchIndex) {
  const textBefore = content.substring(0, matchIndex);
  const lines = textBefore.split("\n");
  for (let i = lines.length - 1; i >= 0; i--) {
    const match = lines[i].match(/^(#{1,6})\s+(.+)$/);
    if (match)
      return lines[i].trim();
  }
  return void 0;
}
function countMatches(content, query) {
  const lowerContent = content.toLowerCase();
  const lowerQuery = query.toLowerCase();
  let count = 0;
  let pos = 0;
  while ((pos = lowerContent.indexOf(lowerQuery, pos)) !== -1) {
    count++;
    pos += lowerQuery.length;
  }
  return count;
}
async function searchInContent(app, query, workingDirectory = "/", excludeFolders = [], limit, previewSize = 100) {
  const searchResults = [];
  const lowerCaseQuery = query.toLowerCase();
  const allNotes = app.vault.getMarkdownFiles();
  for (const note of allNotes) {
    if (isExcludedPath(note.path))
      continue;
    if (!isWithinWorkingDirectory(note.path, workingDirectory))
      continue;
    if (isExcludedByUser(note.path, excludeFolders))
      continue;
    try {
      const content = await app.vault.cachedRead(note);
      const lowerContent = content.toLowerCase();
      if (lowerContent.includes(lowerCaseQuery)) {
        const matchCount = countMatches(content, query);
        const firstIndex = lowerContent.indexOf(lowerCaseQuery);
        const start = Math.max(0, firstIndex - previewSize);
        const end = Math.min(content.length, firstIndex + query.length + previewSize);
        const preview = `...${content.substring(start, end)}...`;
        const nearestHeading = findNearestHeading(content, firstIndex);
        searchResults.push({
          path: note.path,
          type: "file",
          preview,
          match_count: matchCount,
          nearest_heading: nearestHeading
        });
        if (limit && searchResults.length >= limit)
          break;
      }
    } catch (e) {
      console.error(`\u041E\u0448\u0438\u0431\u043A\u0430 \u0447\u0442\u0435\u043D\u0438\u044F \u0444\u0430\u0439\u043B\u0430 ${note.path}:`, e);
    }
  }
  return searchResults;
}
async function searchInNames(app, query, workingDirectory = "/", excludeFolders = [], limit) {
  const searchResults = [];
  const lowerCaseQuery = query.toLowerCase();
  const allItems = app.vault.getAllLoadedFiles();
  for (const item of allItems) {
    if (isExcludedPath(item.path))
      continue;
    if (!isWithinWorkingDirectory(item.path, workingDirectory))
      continue;
    if (isExcludedByUser(item.path, excludeFolders))
      continue;
    if (item.path.toLowerCase().includes(lowerCaseQuery)) {
      searchResults.push({
        path: item.path,
        type: item instanceof import_obsidian42.TFile ? "file" : "folder"
      });
      if (limit && searchResults.length >= limit)
        break;
    }
  }
  return searchResults;
}
async function searchInHeadings(app, query, workingDirectory = "/", excludeFolders = [], limit) {
  const searchResults = [];
  const lowerCaseQuery = query.toLowerCase();
  const allNotes = app.vault.getMarkdownFiles();
  for (const note of allNotes) {
    if (isExcludedPath(note.path))
      continue;
    if (!isWithinWorkingDirectory(note.path, workingDirectory))
      continue;
    if (isExcludedByUser(note.path, excludeFolders))
      continue;
    try {
      const content = await app.vault.cachedRead(note);
      const lines = content.split("\n");
      const matchedHeadings = [];
      for (const line of lines) {
        const headingMatch = line.match(/^(#{1,6})\s+(.+)$/);
        if (headingMatch && line.toLowerCase().includes(lowerCaseQuery)) {
          matchedHeadings.push(line.trim());
        }
      }
      if (matchedHeadings.length > 0) {
        searchResults.push({
          path: note.path,
          type: "file",
          match_count: matchedHeadings.length,
          matched_headings: matchedHeadings,
          nearest_heading: matchedHeadings[0]
        });
        if (limit && searchResults.length >= limit)
          break;
      }
    } catch (e) {
      console.error(`\u041E\u0448\u0438\u0431\u043A\u0430 \u0447\u0442\u0435\u043D\u0438\u044F \u0444\u0430\u0439\u043B\u0430 ${note.path}:`, e);
    }
  }
  return searchResults;
}
function createSearchTool(api, app) {
  return {
    name: "search",
    description: "\u0418\u0449\u0435\u0442 \u0444\u0430\u0439\u043B\u044B \u043F\u043E \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u044E, \u0441\u043E\u0434\u0435\u0440\u0436\u0438\u043C\u043E\u043C\u0443 \u0438\u043B\u0438 \u0437\u0430\u0433\u043E\u043B\u043E\u0432\u043A\u0430\u043C. \u041F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442 \u043C\u043D\u043E\u0436\u0435\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 \u0437\u0430\u043F\u0440\u043E\u0441\u044B.",
    execute: async (params) => {
      const normalized = normalizeParams(params, [
        "query",
        "in_content",
        "mode",
        "folder",
        "exclude_folders",
        "limit",
        "preview_size"
      ]);
      const { query, in_content, mode, folder, exclude_folders, limit, preview_size } = normalized;
      if (!query) {
        throw new Error('\u041F\u0430\u0440\u0430\u043C\u0435\u0442\u0440 "query" \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u0435\u043D');
      }
      const baseWorkingDirectory = params.__workingDirectory || "/";
      let searchMode;
      if (mode) {
        searchMode = mode;
      } else {
        searchMode = in_content ? "content" : "names";
      }
      let effectiveWorkDir = baseWorkingDirectory;
      if (folder) {
        const normalizedFolder = folder.replace(/\\/g, "/").replace(/^\/+/, "").replace(/\/+$/, "");
        if (baseWorkingDirectory === "/" || baseWorkingDirectory === "") {
          effectiveWorkDir = normalizedFolder;
        } else {
          effectiveWorkDir = `${baseWorkingDirectory.replace(/\/+$/, "")}/${normalizedFolder}`;
        }
      }
      const excludeFolders = exclude_folders || [];
      const previewSize = preview_size || 100;
      async function executeSearch(q) {
        switch (searchMode) {
          case "content":
            return searchInContent(app, q, effectiveWorkDir, excludeFolders, limit, previewSize);
          case "headings":
            return searchInHeadings(app, q, effectiveWorkDir, excludeFolders, limit);
          case "names":
          default:
            return searchInNames(app, q, effectiveWorkDir, excludeFolders, limit);
        }
      }
      if (isBatchOperation(query)) {
        const queries = query;
        if (queries.length === 0) {
          throw new Error("\u0421\u043F\u0438\u0441\u043E\u043A \u0437\u0430\u043F\u0440\u043E\u0441\u043E\u0432 \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u043F\u0443\u0441\u0442\u044B\u043C");
        }
        const results = [];
        for (const q of queries) {
          try {
            const matches = await executeSearch(q);
            results.push({
              path: q,
              // Используем запрос как "путь" для консистентности
              status: "success",
              data: {
                query: q,
                mode: searchMode,
                matches,
                total: matches.length,
                working_directory: effectiveWorkDir,
                excluded_folders: excludeFolders.length > 0 ? excludeFolders : void 0
              }
            });
          } catch (e) {
            const errorMessage = e instanceof Error ? translateError(e.message) : "\u041D\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043D\u0430\u044F \u043E\u0448\u0438\u0431\u043A\u0430";
            results.push({
              path: q,
              status: "error",
              error: errorMessage
            });
          }
        }
        return { results };
      } else {
        try {
          const matches = await executeSearch(query);
          return {
            status: "success",
            data: {
              query,
              mode: searchMode,
              matches,
              total: matches.length,
              working_directory: effectiveWorkDir,
              excluded_folders: excludeFolders.length > 0 ? excludeFolders : void 0
            }
          };
        } catch (e) {
          const errorMessage = e instanceof Error ? translateError(e.message) : "\u041D\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043D\u0430\u044F \u043E\u0448\u0438\u0431\u043A\u0430";
          return {
            status: "error",
            error: errorMessage
          };
        }
      }
    }
  };
}

