        const chatView = aiChatView.getChatView();
        if (!chatView) {
          throw new Error("ChatView \u043D\u0435 \u0438\u043D\u0438\u0446\u0438\u0430\u043B\u0438\u0437\u0438\u0440\u043E\u0432\u0430\u043D");
        }
        const childSession = chatView.getCurrentSession();
        if (!childSession) {
          throw new Error("\u0422\u0435\u043A\u0443\u0449\u0430\u044F \u0441\u0435\u0441\u0441\u0438\u044F \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u0430");
        }
        if (!childSession.parentSessionId) {
          throw new Error("\u042D\u0442\u0430 \u0441\u0435\u0441\u0441\u0438\u044F \u043D\u0435 \u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0434\u043E\u0447\u0435\u0440\u043D\u0435\u0439. \u0418\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442 report \u043C\u043E\u0436\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u0432 \u0447\u0430\u0442\u0430\u0445, \u0441\u043E\u0437\u0434\u0430\u043D\u043D\u044B\u0445 \u0447\u0435\u0440\u0435\u0437 startNewChat \u0441 waitForReport=true");
        }
        const parentSessionId = childSession.parentSessionId;
        const pendingManager = PendingToolCallsManager.getInstance();
        if (!pendingManager.hasPendingForSession(parentSessionId)) {
          throw new Error(`\u0420\u043E\u0434\u0438\u0442\u0435\u043B\u044C\u0441\u043A\u0430\u044F \u0441\u0435\u0441\u0441\u0438\u044F ${parentSessionId} \u043D\u0435 \u043E\u0436\u0438\u0434\u0430\u0435\u0442 \u043E\u0442\u0447\u0435\u0442\u0430. \u0412\u043E\u0437\u043C\u043E\u0436\u043D\u043E, \u043E\u043D\u0430 \u0431\u044B\u043B\u0430 \u043E\u0442\u043C\u0435\u043D\u0435\u043D\u0430 \u0438\u043B\u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0430.`);
        }
        const pendingCall = pendingManager.getPendingBySessionId(parentSessionId);
